class WSFrames(list):
    "Captured frames, one per line with the gap since the frame before"
    def __repr__(self):
        res,t0 = [],None
        for f in self:
            res.append(f"{'' if t0 is None else f'+{f.ts-t0:.3f}s '}{f!r}")
            t0 = f.ts
        return '\n'.join(res) or '(no frames)'

